// Generate the interface's TypeScript types from the API's OpenAPI document.
//
// UI-ADR-05: the client's types are GENERATED, never hand-written. Two
// hand-maintained definitions of one shape diverge, and the divergence
// surfaces as a blank column in the interface — which looks exactly like a
// feature nobody has used yet.
//
// The document itself is generated by reflection over the Go response types
// (internal/api/openapi.go), so the chain from the store's schema to the
// client's types has no hand-written link in it.
//
// Run against a live server, or against a document dumped to a file:
//
//	node scripts/gen-types.mjs                      # http://127.0.0.1:8080
//	node scripts/gen-types.mjs path/to/openapi.json
import { writeFileSync, existsSync, readFileSync } from 'node:fs';
import { mkdirSync } from 'node:fs';
import { dirname } from 'node:path';
import openapiTS, { astToString } from 'openapi-typescript';

const source = process.argv[2] ?? (process.env.API_URL ?? 'http://127.0.0.1:8080') + '/v1/schema/openapi.json';
const out = 'src/api/generated/schema.ts';

async function main() {
  let input;
  if (existsSync(source)) {
    input = JSON.parse(readFileSync(source, 'utf8'));
  } else {
    const res = await fetch(source);
    if (!res.ok) throw new Error(`${source} returned ${res.status}`);
    input = await res.json();
  }

  const ast = await openapiTS(input);
  const banner = [
    '/* GENERATED FILE — DO NOT EDIT.',
    ' *',
    ' * Produced by scripts/gen-types.mjs from the API\'s own OpenAPI document,',
    ' * which is itself generated by reflection over the Go response types.',
    ' * Editing this file by hand re-creates the drift the generation exists to',
    ' * prevent (UI-ADR-05, VM-UI-F-107).',
    ' *',
    ` * Source: ${source}`,
    ' */',
    '',
  ].join('\n');

  mkdirSync(dirname(out), { recursive: true });
  writeFileSync(out, banner + astToString(ast));
  console.log(`wrote ${out}`);
}

main().catch((err) => {
  console.error(`gen-types: ${err.message}`);
  console.error(
    'The API server must be running, or a dumped document passed as an argument:\n' +
      '  go run ./cmd/apiserver -demo &\n' +
      '  npm run gen',
  );
  process.exit(1);
});
